#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int nthreads = 1;
    std::vector<long long> blockSums;   // sum of each thread's chunk
    std::vector<long long> blockOffset; // sum of all blocks to the "right" of this thread

#pragma omp parallel
    {
#pragma omp single
        {
            nthreads = omp_get_num_threads();
            blockSums.assign(nthreads, 0LL);
            blockOffset.assign(nthreads, 0LL);
        }

        const int tid = omp_get_thread_num();

        // Static, contiguous partitioning identical to omp for schedule(static)
        const int base = n / nthreads;
        const int rem  = n % nthreads;
        const int start = tid * base + (tid < rem ? tid : rem);
        const int len   = base + (tid < rem ? 1 : 0);
        const int end   = start + len; // exclusive

        // Phase 1: compute local reverse prefix sums within the chunk,
        // and the total sum of the chunk.
        long long running = 0;
        for (int i = end - 1; i >= start; --i) {
            running += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(running); // temporary, will be offset in phase 3
        }

        blockSums[tid] = running;

#pragma omp barrier

        // Phase 2: compute per-block offsets (sum of all blocks to the right).
#pragma omp single
        {
            long long suffix = 0;
            for (int t = nthreads - 1; t >= 0; --t) {
                blockOffset[t] = suffix;
                suffix += blockSums[t];
            }
        }

#pragma omp barrier

        // Phase 3: add the offset to each element in the block.
        const long long off = blockOffset[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + off);
        }
    }
}
